package com.axl.custodian.core.presence;
import com.axl.custodian.api.presence.PhysicalInstance; import com.axl.custodian.api.presence.PhysicalPresence; import com.axl.custodian.api.presence.ProcessEpoch; import com.axl.custodian.api.presence.ScannerScope; import com.axl.custodian.api.shadow.ScopeContribution; import com.axl.custodian.core.storage.sqlite.SqliteCustodianStore; import java.nio.file.Path; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import static org.junit.jupiter.api.Assertions.*;
class ScopeContributorTest { @TempDir Path dir; @Test void partialContributionNeverClosesExistingScopePresence(){Instant now=Instant.EPOCH; try(var store=new SqliteCustodianStore(dir.resolve("c.db"))){UUID a=UUID.randomUUID(),b=UUID.randomUUID();store.adopt(a,"x",now);store.adopt(b,"x",now);var s=new PresenceService(store,Clock.fixed(now,ZoneOffset.UTC),Duration.ofSeconds(10));var e=new ProcessEpoch(UUID.randomUUID(),"s",now,now);s.start(e);s.reconcile(e,"player:a",List.of(new PhysicalPresence(a,e,new PhysicalInstance("player:a:slot:0"),"a",now)));new ScopeContributor(s).contribute(e,new ScopeContribution(new ScannerScope("player:a"),List.of(new PhysicalPresence(b,e,new PhysicalInstance("player:a:slot:1"),"b",now))));assertEquals(2,store.activePresences(a,now).size()+store.activePresences(b,now).size());}} }
